/**
 * @method
 * @name grd_disclosureList_oncellclick
 * @description grd_disclosureList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_disclosureList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_disclosureList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_disclosureList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        /* TODO Stage2: 행 동작 미정의: scwin.fn_Disclsviewer (열 ?) */ await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.fn_Disclsviewer'); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_disclosureList.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_141_onclick
 * @description krxpage_pagenavigator_141 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_141_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_SearchReq').set('pageIndex', pi);
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil20100.krxpage_pagenavigator_141_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/company/companyinfo.do",
        ref: "dma_SearchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_disclosureList_fmt_formEngNm
 * @description grd disclosure List fmt form Eng Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_disclosureList_fmt_formEngNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_disclosureList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "langTpCd") ?? '') : '');
        if (v === '1') { return String((dl && dl.getCellData ? dl.getCellData(r, "formEngNm") : '') ?? ''); }
        return String((dl && dl.getCellData ? dl.getCellData(r, "formKorNm") : '') ?? '');
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_disclosureList.formEngNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_disclosureList_fmt_column4
 * @description grd disclosure List fmt column4 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_disclosureList_fmt_column4 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_disclosureList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "disclsAcptTpCd") ?? '') : '');
        if (v === 'F') { return "최초"; }
        if (v === 'M') { return "정정"; }
        if (v === 'A') { return "첨부추가"; }
        if (v === 'U') { return "첨부정정"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_disclosureList.column4" }); return String(data ?? ''); }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    const frm = (document.disclosureForm || { elements: [] });
    if ($c.util.getComponent('cal_sdate').getValue()> $c.util.getComponent('cal_edate').getValue()) {
        await $c.win.alert('시작일이 종료일보다 이후 일자 입니다.');
        return;
    }
    $c.util.getComponent('dma_SearchReq').set('method', 'searchDisclosure');
    frm.action = 'companyinfo.do';
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name setSearchPeriod
 * @description 조회 기간 버튼 — 오늘을 종료일로, 구분에 따라 시작일을 계산해 넣고 조회(as-is 공통 fn_ClickPeriod)
 * @param {*} type 1 1주 · 2 1개월 · 3 3개월 · 4 6개월 · 5 1년 · 6 2년 · 7 3년
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setSearchPeriod = async function (type) {
    const edate = $c.date.getServerDateTime("yyyyMMdd");
    const offsets = { 1: ["addDate", -7], 2: ["addMonth", -1], 3: ["addMonth", -3], 4: ["addMonth", -6], 5: ["addYear", -1], 6: ["addYear", -2], 7: ["addYear", -3] };
    const o = offsets[Number(type)];
    const sdate = o ? $c.date[o[0]](edate, o[1]) : edate;
    await scwin.setPeriodDates(sdate, edate);
};

/**
 * @method
 * @name setPeriodDates
 * @description 조회 기간(시작일·종료일)을 달력에 넣고 바로 조회(as-is 공통 fn_SetPeriod → fn_Search)
 * @param {*} sdate 시작일(yyyyMMdd)
 * @param {*} edate 종료일(yyyyMMdd)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setPeriodDates = async function (sdate, edate) {
    $c.util.getComponent("cal_sdate").setValue(sdate);
    $c.util.getComponent("cal_edate").setValue(edate);
    await scwin.search();
};
